argv:
set -e
D=products/services/ghost-migration/portable-reproduction
mkdir -p $D/tests/stubs
cat > $D/package.json <<'EOF'
{
 "name": "ghost-blockquote-br-repro",
 "version": "0.1.0",
 "private": true,
 "description": "Portable converter-level reproduction for Ghost forum report t/60053 (blockquote with <br>). Built by autonomous AI agents (GlobalLand). Unvalidated.",
 "license": "MIT",
 "engines": {"node": "^22.22.2 || ^24.15.0"},
 "dependencies": {"@tryghost/kg-html-to-lexical": "1.4.4"},
 "scripts": {"repro": "node harness.cjs --out result.json", "test:stubs": "node tests/run-stub-tests.cjs"}
}
EOF
cat > $D/fixtures.json <<'EOF'
{
 "note": "Synthetic inputs. Built by autonomous AI agents (GlobalLand). Expected observations describe what each outcome would mean; they are not observed upstream results.",
 "cases": [
  {"id": "q1-before", "question": "Q1", "html": "<blockquote>a<br>b</blockquote>", "tokens": ["a", "b"], "quote_tokens": ["a", "b"], "min_quote_nodes": 1, "quote_linebreaks": 1,
   "if_report_reproduces": "FAIL with a and/or b in missing_tokens while linebreaks remain", "if_not": "PASS"},
  {"id": "q2-after", "question": "Q2", "html": "<blockquote><p>a<br>b</p></blockquote>", "tokens": ["a", "b"], "quote_tokens": ["a", "b"], "min_quote_nodes": 1, "quote_linebreaks": 1,
   "if_workaround_hypothesis_holds": "PASS", "if_not": "FAIL: the p-wrapping hypothesis is refuted for this converter"},
  {"id": "q3-ws-before", "question": "Q3", "html": "<blockquote>  a<br>b \n</blockquote>", "tokens": ["a", "b"], "min_quote_nodes": 1,
   "observe": "raw texts show whether leading/trailing whitespace survives conversion"},
  {"id": "q3-ws-after", "question": "Q3", "html": "<blockquote><p>a<br>b</p></blockquote>", "tokens": ["a", "b"], "min_quote_nodes": 1},
  {"id": "q4-nested-a", "question": "Q4", "html": "<blockquote>a<blockquote>b<br>c</blockquote>d</blockquote>", "tokens": ["a", "b", "c", "d"], "min_quote_nodes": 1,
   "observe": "quote_types, quote_linebreaks and lexical show how nesting is handled; no linebreak count is asserted"},
  {"id": "q4-nested-b", "question": "Q4", "html": "<blockquote>x<br>y<blockquote>z</blockquote></blockquote>", "tokens": ["x", "y", "z"], "min_quote_nodes": 1,
   "observe": "as q4-nested-a"},
  {"id": "control-plain-quote", "question": "control", "html": "<blockquote>No breaks here</blockquote>", "tokens": ["No breaks here"], "min_quote_nodes": 1, "quote_linebreaks": 0},
  {"id": "control-paragraph-br", "question": "control", "html": "<p>a<br>b</p>", "tokens": ["a", "b"], "min_quote_nodes": 0}
 ],
 "pairs": [
  {"a": "q3-ws-before", "b": "q3-ws-after", "question": "Q3: same normalized text and linebreak count after conversion"}
 ]
}
EOF
cat > $D/tests/stubs/stub-common.cjs <<'EOF'
'use strict';
// STUB converter for harness control-flow tests ONLY. It is not Ghost and not @tryghost/kg-html-to-lexical.
function seg(html) { return html.replace(/<(?!br\s*\/?>)[^>]*>/gi, '').split(/<br\s*\/?>/i); }
function build(html, lossy) {
  const kids = [];
  seg(html).forEach((p, i) => { if (i > 0) kids.push({type: 'linebreak', version: 1}); if (p.length) kids.push({type: 'extended-text', text: p, version: 1}); });
  const isQuote = /<blockquote/i.test(html);
  let children = kids;
  if (isQuote && lossy && /<br/i.test(html) && !/<p[\s>]/i.test(html)) children = kids.filter(k => k.type === 'linebreak');
  return {root: {type: 'root', children: [{type: isQuote ? 'extended-quote' : 'paragraph', children}]}};
}
module.exports = {build};
EOF
printf "'use strict';\n// STUB: preserves all text.\nconst {build} = require('./stub-common.cjs');\nmodule.exports = {htmlToLexical: h => build(h, false)};\n" > $D/tests/stubs/stub-preserving.cjs
printf "'use strict';\n// STUB: drops text in quotes containing <br> without <p>, imitating the reported symptom.\nconst {build} = require('./stub-common.cjs');\nmodule.exports = {htmlToLexical: h => build(h, true)};\n" > $D/tests/stubs/stub-lossy.cjs
printf "'use strict';\n// STUB: returns a JSON string instead of an object.\nconst {build} = require('./stub-common.cjs');\nmodule.exports = {htmlToLexical: h => JSON.stringify(build(h, false))};\n" > $D/tests/stubs/stub-string.cjs
printf "'use strict';\n// STUB: converter that always throws.\nmodule.exports = {htmlToLexical() { throw new Error('STUB: simulated converter exception'); }};\n" > $D/tests/stubs/stub-throws.cjs
printf "'use strict';\n// STUB: module without the expected export.\nmodule.exports = {somethingElse() {}};\n" > $D/tests/stubs/stub-noexport.cjs
for f in $D/tests/stubs/*.cjs; do node --check $f; done
node -e "for (const f of ['fixtures.json','package.json']) JSON.parse(require('fs').readFileSync('$D/'+f,'utf8')); console.log('json-ok')"
